import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"54、【归妹】 兑下震上","description":"周易口诀义 - 54、【归妹】 兑下震上","frontmatter":{"title":"54、【归妹】 兑下震上","description":"周易口诀义 - 54、【归妹】 兑下震上"},"headers":[],"relativePath":"zh/classics/koujueyi/056.md","filePath":"zh/classics/koujueyi/056.md"}'),r={name:"zh/classics/koujueyi/056.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_54、【归妹】-兑下震上" tabindex="-1">54、【归妹】 兑下震上 <a class="header-anchor" href="#_54、【归妹】-兑下震上" aria-label="Permalink to “54、【归妹】 兑下震上”">​</a></h1><p>彖曰：归妹，天地之大义也。天地不交而万物不兴。「归妹」，人之终始也。说以动，所「归妹」也。「征凶」，位不当也。「无攸利」，柔乘刚也。</p><p>象曰：泽上有雷，「归妹」。君子以永终知敝。</p><p>初九：归妹以娣，跛能履，征吉。</p><p>象曰：「归妹以娣」，以恒也。「跛能履吉」，相承也。</p><p>九二，眇能视，利幽人之贞。</p><p>象曰：「利幽人之贞」，未变常也。</p><p>六三，归妹以须，反归以娣。</p><p>象曰：「归妹以须」，未当也。</p><p>九四，归妹愆期，迟归有时。</p><p>象曰：「愆期」之志，有待而行也。</p><p>六五，帝乙归妹，其君之袂，不如其娣之袂良，月几望，吉。</p><p>象曰：「帝乙归妹，不如其娣之袂良」也，其位在中，以贵行也。</p><p>上六，女承筐无实，士刲羊无血，无攸利。</p><p>象曰：上六「无实」，承虚筐也。</p><p>解读</p><p>归妹者，女人以嫁为归，归妹即是从姊而嫁，故曰「归妹」也。然古者诸侯一娶九女，侄娣从之。虞翻云：「九女者，贵其男女继嗣，宗享不绝也。」「征凶无攸利」者，征谓进而求宠也，妹从姊而行，固宜卑退，敬事女后，若妄求进宠，希谓并后，即有并后之乱，凶祸斯至而无利，故曰「征凶无攸利」也。</p><p>象曰「泽上有雷，归妹」者，泽上有雷，悦而有动，「归妹之象也。君子以永终知敝」者，诸儒于此，各以意见，互说不同，不可随波而流，弥增惑乱，今则取师说为义也。所以一娶九女者，贵其蕃育继嗣，宗享不绝，则是永长延祚，保后之终。若九女无子，即绝其后嗣，即有不终之敝。盖为正经云「天地之大义」，人伦之终始矣。</p><p>「初九，归妹以娣，跛能履，征吉」者，少女谓之娣也。以兑适震，以幼从长，非其匹配，是从姊而行，故「归妹以娣」也。虽不失其道，然幼从长，譬之跛足之人，足虽蹇跛，不妨履践，故曰「跛能履」。妹从姊行，不可僭进，为嫡即凶，为娣即吉，故曰「征吉」也。</p><p>「九二，眇能视，利幽人之贞」者，位虽不正，而居内处中，守其卑礼，不能妄进，犹如眇目之人，不妨所视，故曰「眇能视」也；居内守中，不失常道，是居幽而不亏其正，故曰「利幽人之贞」也。</p><p>「六三，归妹以须，反归以娣」者，六三处下卦之上，位又不正，即是僭进，求为室主，室主犹存，进不值时，故宜待时，故曰「归妹以须」也；既不值时，固当反归，且为娣从，俟时而进，故曰「反归以娣」也。</p><p>「九四，归妹愆期，迟归有时」者，以阳居阴位不正也；下又无应，以不正无应而行，是为妄进，故须愆过于期，若有所适，候彼道穷尽，待时而行，然后可往，故「迟归有时」也。</p><p>「六五，帝乙归妹，其君之袂，不如其娣之袂良。月几望，吉」者，居得尊位，应在九二，是帝王嫁妹，以降于二，故曰「帝乙归妹」。袂者，衣袖为礼容，帝王嫁妹，则以衣裳为崇饰也。其君即五也，应在九二，以震适兑，以长从幼，即是降尊就卑，不如以卑就尊，合于常道，故曰「君之袂，不如其娣之袂良」。月，阴之盛，犹如月，近望可以敌日，以贵而行，以斯适配，往亦必合，故「月几望，吉」。几，近也；阴盛为位在于中，以贵而行也。</p><p>「上六，女承筐无实，士刲羊无血，无攸利」者，女子之行，以承顺为德，士之为道，以下之应命为美。今上六居卦之上而无承应，其犹女子承捧虚筐，空无所有。筐本盛币帛，今既空虚，即上无所奉，故曰「女承筐无实」也。下既无应，人不奉命，譬之刲刺其羊而无血矣。羊本有血，今既无血，即是教令不行，故曰「士刲羊无血」。进退莫与，故曰「无攸利」。羊谓六三也。</p>',24)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
